/**
 * Phase I3: Shim code generator.
 * Given library usage scan results + shim database, generates complete shim .ts files.
 */

import { findShim, type ShimEntry } from "./shim-database.js";
import type { LibraryUsage } from "./library-scanner.js";

/**
 * Generate a complete shim TypeScript file for the given library usages.
 */
export function generateShimFile(usages: LibraryUsage[]): string {
  const lines: string[] = [
    "/**",
    " * Auto-generated library shims.",
    " * Generated by src2ts shim-generator.",
    " */",
    "",
  ];

  let implemented = 0;
  let stubbed = 0;

  for (const usage of usages) {
    const shim = findShim(usage.cFunction);
    if (shim) {
      lines.push(`export function ${shim.cFunction}(${shim.params}): ${shim.returnType} { ${shim.tsCode} }`);
      implemented++;
    } else {
      lines.push(`export function ${usage.cFunction}(...args: any[]): any { console.warn("[shim] STUB: ${usage.cFunction}"); }`);
      stubbed++;
    }
  }

  lines.push("");
  lines.push(`// ${implemented} implemented, ${stubbed} stubbed`);
  lines.push(`console.log("[shims] ${implemented} implemented + ${stubbed} stubbed = ${implemented + stubbed} total");`);

  return lines.join("\n");
}

/**
 * Generate a stub function for a C function with no shim and no source.
 * Logs a warning at runtime so developers know which functions are unimplemented.
 */
export function generateStubFunction(cFunction: string): string {
  return `export function ${cFunction}(...args: any[]): any { console.warn("[shim] STUB: ${cFunction} — no shim or source available"); }`;
}

/**
 * Generate shims and register them on globalThis.
 */
export function generateShimLoader(usages: LibraryUsage[]): string {
  const lines: string[] = [
    "/**",
    " * Auto-generated shim loader — registers all shims on globalThis.",
    " */",
    "",
    "import * as shims from './generated-shims.js';",
    "",
    "for (const [name, value] of Object.entries(shims)) {",
    "  if (typeof value === 'function') {",
    "    (globalThis as any)[name] = value;",
    "  }",
    "}",
  ];

  return lines.join("\n");
}
